import Foundation

/// The reviewed Simple7702Account deployment from Ethereum transaction
/// 0xec085203f082d7285211929483a6df7b974cf854cedfdf5d50b22f4f0f833826.
public enum Simple7702AccountDeployment {
  public static let factory = "0x4e59b44847b379578588920cA78FbF26c0B4956C"
  public static let factoryRuntimeHash =
    "0x2fa86add0aed31f33a762c9d88e807c475bd51d0f52bd0955754b2608f7e4989"
  public static let salt = String(repeating: "00", count: 32)
  public static let calldataHash =
    "0x414122fad5a970579482e95a967d40376305e3e120dad055e75f0821360b679e"

  public static let creationCode =
    "0x"
    + [
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "5b5050505f916003919056fea26469706673582212203510a380b939736f9c72aa0e20651e01f3c432a0c3b3345510f551189d5d889f64736f6c634300081c0033",
    ].joined()

  public static var calldata: String {
    "0x" + salt + creationCode.dropFirst(2)
  }

  public static func isValid() -> Bool {
    guard let factoryBytes = Hex.data(factory), factoryBytes.count == 20,
      let saltBytes = Hex.data("0x" + salt), saltBytes.count == 32,
      let creationBytes = Hex.data(creationCode),
      let calldataBytes = Hex.data(calldata)
    else { return false }
    let calldataDigest = "0x" + Hex.encode(Keccak.keccak256(calldataBytes))
    guard calldataDigest.caseInsensitiveCompare(calldataHash) == .orderedSame else { return false }
    let digest = Keccak.keccak256(
      [0xff] + factoryBytes + saltBytes + Keccak.keccak256(creationBytes))
    let derived = "0x" + Hex.encode(Array(digest.suffix(20)))
    return derived.caseInsensitiveCompare(EIP5792.simple7702Account) == .orderedSame
  }
}
